"""EUDC half of the extend table: PUA rows survive, hex slots expand (#868).

The engine reads ``chardefs`` straight from the committed JSON, so the
``ignorePrivateUseArea`` branch of ``Cin.__init__`` is the only thing between
a PUA row of the .cin source and the candidate window, and
``extendtable.__init__`` is the only thing between a 自訂擴展碼表 line and the
merged table. This module pins both against the real ``bpmf.json`` and a real
in-memory extendtable, and one merge through ``Cin.updateCinTable`` for the
priority and append positions.
"""

import importlib.util
import io
import json
import os
import sys
import unittest

ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), os.pardir))
PYTHON_DIR = os.path.join(ROOT, "python")
CINBASE = os.path.join(PYTHON_DIR, "cinbase")
JSON_DIR = os.path.join(CINBASE, "json")
CIN_PY = os.path.join(CINBASE, "cin.py")
EXTENDTABLE_PY = os.path.join(CINBASE, "extendtable.py")

# The 兀 row of j4 exists twice in the table: the Big5 glyph and the PUA copy
# the privateuse dict names; cji4 pairs 嗀 with its own PUA copy the same way.
WU_BIG5 = "\u5140"   # 兀
WU_PUA = "\ufa0c"    # PUA copy, stripped only when ignorePrivateUseArea is on
HUO_BIG5 = "\u55c0"  # 嗀
HUO_PUA = "\ufa0d"   # PUA copy


def load_by_path(name, path):
    """Import a module by path, like test_cinbase_tables.py does for the tools."""
    spec = importlib.util.spec_from_file_location(name, path)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


if PYTHON_DIR not in sys.path:
    sys.path.insert(0, PYTHON_DIR)  # cin.py imports pimepaths from python/
cin_module = load_by_path("eudc_cin", CIN_PY)
extendtable_module = load_by_path("eudc_extendtable", EXTENDTABLE_PY)


def load_json(name):
    with open(os.path.join(JSON_DIR, name), encoding="utf-8") as handle:
        return json.load(handle)


class EudcPrivateUseAreaTests(unittest.TestCase):
    """Cin keeps the PUA copies when the flag is off and strips exactly the
    privateuse rows when it is on."""

    @classmethod
    def setUpClass(cls):
        cls.raw = load_json("bpmf.json")

    def build(self, ignore_private_use_area):
        with open(os.path.join(JSON_DIR, "bpmf.json"), encoding="utf-8") as fs:
            return cin_module.Cin(fs, "bpmf", ignore_private_use_area)

    def test_flag_off_keeps_every_row_verbatim(self):
        cin = self.build(False)
        self.assertEqual(cin.chardefs, self.raw["chardefs"])
        self.assertEqual(cin.chardefs["j4"].count(WU_BIG5), 1)
        self.assertEqual(cin.chardefs["j4"].count(WU_PUA), 1)
        self.assertEqual(cin.chardefs["cji4"].count(HUO_PUA), 1)

    def test_flag_on_strips_exactly_the_privateuse_rows(self):
        cin = self.build(True)
        for key in self.raw["privateuse"]:
            before = self.raw["chardefs"][key]
            after = cin.chardefs[key]
            for value in self.raw["privateuse"][key]:
                self.assertEqual(after.count(value), before.count(value) - 1)
            self.assertEqual(len(after), len(before) - len(self.raw["privateuse"][key]))
        # The non-PUA neighbours around the stripped row survive ...
        self.assertIn("\u52ff", cin.chardefs["j4"])  # 勿
        self.assertIn("\u7269", cin.chardefs["j4"])  # 物
        self.assertIn(WU_BIG5, cin.chardefs["j4"])   # Big5 兀 stays
        self.assertIn(HUO_BIG5, cin.chardefs["cji4"])
        # ... and nothing else moved.
        for key in self.raw["chardefs"]:
            if key not in self.raw["privateuse"]:
                self.assertEqual(cin.chardefs[key], self.raw["chardefs"][key])


class ExtendTableCodePositionTests(unittest.TestCase):
    """A bare hex code position becomes its character; everything else is
    the stripped string it was."""

    def load(self, text):
        return extendtable_module.extendtable(io.StringIO(text))

    def test_hex_code_positions_expand_and_plain_values_stay(self):
        table = self.load(
            "xx 懲\n"
            "xx FA40\n"
            "qq 0x4e2d\n"
            "ww fa40\n"
            "ee 0X4E2D\n"
            "ff 4e2d\n"
            "AB abc\n"
            "zz"
        )
        # The literal row keeps its Big5 glyph (懲 is U+61F2); the two hex
        # forms give the code point itself, and chr(0xFA40) is the PUA copy
        # EUDCEDIT holds for 懲. chr(0x4E2D) is the very 中 the table carries.
        self.assertEqual(table.chardefs["xx"], ["懲", "\ufa40"])
        self.assertEqual(table.chardefs["qq"], ["中"])
        self.assertEqual(table.chardefs["ww"], ["\ufa40"])
        self.assertEqual(table.chardefs["ee"], ["中"])
        self.assertEqual(table.chardefs["ff"], ["中"])
        self.assertEqual(table.chardefs["ab"], ["abc"])
        self.assertNotIn("AB", table.chardefs)  # keys keep the lowercase norm
        self.assertEqual(table.chardefs["zz"], ["Error"])

    def test_out_of_range_and_short_values_stay_strings(self):
        table = self.load("gg 0xFFFFF\nhh 4e2\nii 0x4e2d ")
        # 0xFFFFF is the five-digit cap, inside U+10FFFF, so it expands too;
        # a three-digit run is no code position at all.
        self.assertEqual(table.chardefs["gg"], ["\U000fffff"])
        self.assertEqual(table.chardefs["hh"], ["4e2"])
        self.assertEqual(table.chardefs["ii"], ["中"])


class ExtendTableMergeTests(unittest.TestCase):
    """One merged table through Cin.updateCinTable: the priority flag
    inserts at the extend-list index, without it rows append, and the PUA
    character of the live table survives the merge with the flag off."""

    def build(self):
        with open(os.path.join(JSON_DIR, "bpmf.json"), encoding="utf-8") as fs:
            return cin_module.Cin(fs, "bpmf", False)

    def make_extend(self):
        return extendtable_module.extendtable(io.StringIO("j4 AA\nj4 BB\nnn CC"))

    def test_priority_inserts_at_the_documented_index(self):
        cin = self.build()
        base = list(cin.chardefs["j4"])
        cin.updateCinTable(True, True, self.make_extend(), False)
        self.assertEqual(cin.chardefs["j4"][:2], ["AA", "BB"])
        self.assertEqual(cin.chardefs["j4"][2:], base)
        self.assertEqual(cin.chardefs["nn"], ["CC"])  # new key, created in place
        self.assertIn(WU_PUA, cin.chardefs["j4"])     # PUA survives, flag off

    def test_append_when_not_priority(self):
        cin = self.build()
        base = list(cin.chardefs["j4"])
        cin.updateCinTable(True, False, self.make_extend(), False)
        self.assertEqual(cin.chardefs["j4"], base + ["AA", "BB"])
        self.assertEqual(cin.chardefs["nn"], ["CC"])
        self.assertIn(WU_PUA, cin.chardefs["j4"])

    def test_user_extend_table_off_leaves_the_table_untouched(self):
        cin = self.build()
        base = dict(cin.chardefs)
        cin.updateCinTable(False, True, self.make_extend(), False)
        self.assertEqual(cin.chardefs, base)


if __name__ == "__main__":
    unittest.main()
